namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil",
            Ratings = [5, 4, 5, 4]
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken\n3. Sauté onions, garlic, ginger\n4. Add tomato sauce and cream\n5. Simmer with chicken pieces",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheese, Sour cream",
            Steps = "1. Brown ground beef\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble with toppings",
            Ratings = [4, 4, 5]
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime",
            Steps = "1. Soak noodles in warm water\n2. Stir-fry shrimp and eggs\n3. Add noodles and sauce\n4. Toss with bean sprouts\n5. Garnish with peanuts and lime",
            Ratings = [5, 4, 5, 5]
        },
        new()
        {
            Id = 5, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook pasta al dente\n2. Crisp guanciale in a pan\n3. Whisk eggs with cheese and pepper\n4. Toss hot pasta with guanciale\n5. Stir in egg mixture off heat",
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Baking soda, Chocolate chips",
            Steps = "1. Cream butter and sugars\n2. Beat in eggs and vanilla\n3. Mix in flour and baking soda\n4. Fold in chocolate chips\n5. Bake at 375°F for 9-11 minutes",
            Ratings = [5, 4, 5]
        }
    ];

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

